/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (NET_REP_MAX bytes) and the handles it carries
 * into rhs (IDL_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the request has no txid, or a `later`
 * handler answers it itself). No I/O; the caller sends the reply with the
 * handles, or closes them if it can't. */
static inline uint32_t net_dispatch_on(handle_t ch, const struct net_ops *ops, void *ctx,
                                       const void *req, uint32_t n, void *rep, handle_t *rhs,
                                       uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    if (n < sizeof(uint32_t))
        return 0;
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    if (n < sizeof(struct idl_req_hdr))
        return sizeof(*idl_h);
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case NET_IFACE: {
        const struct net_iface_req *idl_q = (const struct net_iface_req *)req;
        struct net_iface_rep *idl_r = (struct net_iface_rep *)rep;
        uint32_t out_address = 0;
        uint32_t out_mask = 0;
        uint32_t out_gateway = 0;
        uint32_t out_dns1 = 0;
        uint32_t out_dns2 = 0;
        uint8_t out_mac[6];
        for (uint32_t idl_i = 0; idl_i < 6; idl_i++)
            out_mac[idl_i] = 0;
        uint8_t out_device = 0;
        uint8_t out_link = 0;
        uint16_t out_vlan = 0;
        uint32_t out_speed = 0;
        uint32_t out_version = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->iface) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->iface(ctx, &out_address, &out_mask, &out_gateway, &out_dns1, &out_dns2, out_mac, &out_device, &out_link, &out_vlan, &out_speed, &out_version);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->address = out_address;
        idl_r->mask = out_mask;
        idl_r->gateway = out_gateway;
        idl_r->dns1 = out_dns1;
        idl_r->dns2 = out_dns2;
        for (uint32_t idl_i = 0; idl_i < 6; idl_i++)
            idl_r->mac[idl_i] = out_mac[idl_i];
        idl_r->device = out_device;
        idl_r->link = out_link;
        idl_r->vlan = out_vlan;
        idl_r->speed = out_speed;
        idl_r->version = out_version;
        return sizeof(*idl_r);
    }
    case NET_WAIT_CHANGE: {
        const struct net_wait_change_req *idl_q = (const struct net_wait_change_req *)req;
        struct net_wait_change_rep *idl_r = (struct net_wait_change_rep *)rep;
        uint32_t out_version = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->wait_change) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->wait_change(ctx, idl_txn, idl_q->version, idl_q->timeout_ms, &out_version);
        /* IDL_LATER: the handler answers with net_reply_wait_change. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->version = out_version;
        return sizeof(*idl_r);
    }
    case NET_COUNTS: {
        const struct net_counts_req *idl_q = (const struct net_counts_req *)req;
        struct net_counts_rep *idl_r = (struct net_counts_rep *)rep;
        uint8_t out_counts[256];
        for (uint32_t idl_i = 0; idl_i < 256; idl_i++)
            out_counts[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->counts) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->counts(ctx, out_counts);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        for (uint32_t idl_i = 0; idl_i < 256; idl_i++)
            idl_r->counts[idl_i] = out_counts[idl_i];
        return sizeof(*idl_r);
    }
    case NET_CHIP_COUNTS: {
        const struct net_chip_counts_req *idl_q = (const struct net_chip_counts_req *)req;
        struct net_chip_counts_rep *idl_r = (struct net_chip_counts_rep *)rep;
        uint8_t out_counts[256];
        for (uint32_t idl_i = 0; idl_i < 256; idl_i++)
            out_counts[idl_i] = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->chip_counts) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->chip_counts(ctx, idl_txn, out_counts);
        /* IDL_LATER: the handler answers with net_reply_chip_counts. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        for (uint32_t idl_i = 0; idl_i < 256; idl_i++)
            idl_r->counts[idl_i] = out_counts[idl_i];
        return sizeof(*idl_r);
    }
    case NET_UDP: {
        const struct net_udp_req *idl_q = (const struct net_udp_req *)req;
        struct net_udp_rep *idl_r = (struct net_udp_rep *)rep;
        handle_t out_socket = HANDLE_INVALID;
        uint16_t out_port = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->udp) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->udp(ctx, idl_q->port, &out_socket, &out_port);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_socket != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_socket != HANDLE_INVALID)
                drv_handle_close(out_socket);
            return sizeof(*idl_h);
        }
        rhs[0] = out_socket;
        *rhn = 1;
        idl_r->port = out_port;
        return sizeof(*idl_r);
    }
    case NET_ECHO: {
        const struct net_echo_req *idl_q = (const struct net_echo_req *)req;
        struct net_echo_rep *idl_r = (struct net_echo_rep *)rep;
        uint32_t out_rtt_us = 0;
        uint8_t out_ttl = 0;
        uint16_t out_size = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->echo) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->echo(ctx, idl_txn, idl_q->address, idl_q->seq, idl_q->size, idl_q->timeout_ms, &out_rtt_us, &out_ttl, &out_size);
        /* IDL_LATER: the handler answers with net_reply_echo. */
        if (idl_st == IDL_LATER)
            return 0;
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->rtt_us = out_rtt_us;
        idl_r->ttl = out_ttl;
        idl_r->size = out_size;
        return sizeof(*idl_r);
    }
    case NET_UDP_RINGS: {
        const struct net_udp_rings_req *idl_q = (const struct net_udp_rings_req *)req;
        struct net_udp_rings_rep *idl_r = (struct net_udp_rings_rep *)rep;
        handle_t out_socket = HANDLE_INVALID;
        handle_t out_ring = HANDLE_INVALID;
        handle_t out_to_stack = HANDLE_INVALID;
        handle_t out_to_prog = HANDLE_INVALID;
        uint16_t out_port = 0;
        uint32_t out_tx_bytes = 0;
        uint32_t out_rx_bytes = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->udp_rings) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->udp_rings(ctx, idl_q->port, idl_q->tx_bytes, idl_q->rx_bytes, &out_socket, &out_ring, &out_to_stack, &out_to_prog, &out_port, &out_tx_bytes, &out_rx_bytes);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_socket != HANDLE_INVALID && out_ring != HANDLE_INVALID && out_to_stack != HANDLE_INVALID && out_to_prog != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_socket != HANDLE_INVALID)
                drv_handle_close(out_socket);
            if (out_ring != HANDLE_INVALID)
                drv_handle_close(out_ring);
            if (out_to_stack != HANDLE_INVALID)
                drv_handle_close(out_to_stack);
            if (out_to_prog != HANDLE_INVALID)
                drv_handle_close(out_to_prog);
            return sizeof(*idl_h);
        }
        rhs[0] = out_socket;
        rhs[1] = out_ring;
        rhs[2] = out_to_stack;
        rhs[3] = out_to_prog;
        *rhn = 4;
        idl_r->port = out_port;
        idl_r->tx_bytes = out_tx_bytes;
        idl_r->rx_bytes = out_rx_bytes;
        return sizeof(*idl_r);
    }
    case NET_SOCK_CONNECT: {
        const struct net_sock_connect_req *idl_q = (const struct net_sock_connect_req *)req;
        struct net_sock_connect_rep *idl_r = (struct net_sock_connect_rep *)rep;
        (void)idl_r;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->sock_connect) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->sock_connect(ctx, idl_q->address, idl_q->port);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        return sizeof(*idl_r);
    }
    case NET_SOCK_STATE: {
        const struct net_sock_state_req *idl_q = (const struct net_sock_state_req *)req;
        struct net_sock_state_rep *idl_r = (struct net_sock_state_rep *)rep;
        uint16_t out_port = 0;
        uint32_t out_peer = 0;
        uint16_t out_peer_port = 0;
        uint32_t out_queued = 0;
        uint32_t out_dropped = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->sock_state) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->sock_state(ctx, &out_port, &out_peer, &out_peer_port, &out_queued, &out_dropped);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status != OK)
            return sizeof(*idl_h);
        idl_r->port = out_port;
        idl_r->peer = out_peer;
        idl_r->peer_port = out_peer_port;
        idl_r->queued = out_queued;
        idl_r->dropped = out_dropped;
        return sizeof(*idl_r);
    }
    case NET_SOCK_RINGS: {
        const struct net_sock_rings_req *idl_q = (const struct net_sock_rings_req *)req;
        struct net_sock_rings_rep *idl_r = (struct net_sock_rings_rep *)rep;
        handle_t out_ring = HANDLE_INVALID;
        handle_t out_to_stack = HANDLE_INVALID;
        handle_t out_to_prog = HANDLE_INVALID;
        uint32_t out_tx_bytes = 0;
        uint32_t out_rx_bytes = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->sock_rings) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->sock_rings(ctx, idl_q->tx_bytes, idl_q->rx_bytes, &out_ring, &out_to_stack, &out_to_prog, &out_tx_bytes, &out_rx_bytes);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_ring != HANDLE_INVALID && out_to_stack != HANDLE_INVALID && out_to_prog != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_ring != HANDLE_INVALID)
                drv_handle_close(out_ring);
            if (out_to_stack != HANDLE_INVALID)
                drv_handle_close(out_to_stack);
            if (out_to_prog != HANDLE_INVALID)
                drv_handle_close(out_to_prog);
            return sizeof(*idl_h);
        }
        rhs[0] = out_ring;
        rhs[1] = out_to_stack;
        rhs[2] = out_to_prog;
        *rhn = 3;
        idl_r->tx_bytes = out_tx_bytes;
        idl_r->rx_bytes = out_rx_bytes;
        return sizeof(*idl_r);
    }
    case NET_TCP: {
        const struct net_tcp_req *idl_q = (const struct net_tcp_req *)req;
        struct net_tcp_rep *idl_r = (struct net_tcp_rep *)rep;
        handle_t out_socket = HANDLE_INVALID;
        handle_t out_ring = HANDLE_INVALID;
        handle_t out_to_stack = HANDLE_INVALID;
        handle_t out_to_prog = HANDLE_INVALID;
        uint16_t out_port = 0;
        uint32_t out_tx_bytes = 0;
        uint32_t out_rx_bytes = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->tcp) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->tcp(ctx, idl_q->address, idl_q->port, idl_q->tx_bytes, idl_q->rx_bytes, &out_socket, &out_ring, &out_to_stack, &out_to_prog, &out_port, &out_tx_bytes, &out_rx_bytes);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_socket != HANDLE_INVALID && out_ring != HANDLE_INVALID && out_to_stack != HANDLE_INVALID && out_to_prog != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_socket != HANDLE_INVALID)
                drv_handle_close(out_socket);
            if (out_ring != HANDLE_INVALID)
                drv_handle_close(out_ring);
            if (out_to_stack != HANDLE_INVALID)
                drv_handle_close(out_to_stack);
            if (out_to_prog != HANDLE_INVALID)
                drv_handle_close(out_to_prog);
            return sizeof(*idl_h);
        }
        rhs[0] = out_socket;
        rhs[1] = out_ring;
        rhs[2] = out_to_stack;
        rhs[3] = out_to_prog;
        *rhn = 4;
        idl_r->port = out_port;
        idl_r->tx_bytes = out_tx_bytes;
        idl_r->rx_bytes = out_rx_bytes;
        return sizeof(*idl_r);
    }
    case NET_TCP_LISTENER: {
        const struct net_tcp_listener_req *idl_q = (const struct net_tcp_listener_req *)req;
        struct net_tcp_listener_rep *idl_r = (struct net_tcp_listener_rep *)rep;
        handle_t out_listener = HANDLE_INVALID;
        uint16_t out_port = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->tcp_listener) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        status_t idl_st = ops->tcp_listener(ctx, idl_q->port, idl_q->backlog, idl_q->tx_bytes, idl_q->rx_bytes, &out_listener, &out_port);
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_listener != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_listener != HANDLE_INVALID)
                drv_handle_close(out_listener);
            return sizeof(*idl_h);
        }
        rhs[0] = out_listener;
        *rhn = 1;
        idl_r->port = out_port;
        return sizeof(*idl_r);
    }
    case NET_ACCEPT: {
        const struct net_accept_req *idl_q = (const struct net_accept_req *)req;
        struct net_accept_rep *idl_r = (struct net_accept_rep *)rep;
        handle_t out_socket = HANDLE_INVALID;
        handle_t out_ring = HANDLE_INVALID;
        handle_t out_to_stack = HANDLE_INVALID;
        handle_t out_to_prog = HANDLE_INVALID;
        uint32_t out_peer = 0;
        uint16_t out_peer_port = 0;
        uint32_t out_tx_bytes = 0;
        uint32_t out_rx_bytes = 0;
        if (n != sizeof(*idl_q))
            return sizeof(*idl_h);
        if (!ops->accept) {
            idl_h->status = ERR_NOT_SUPPORTED;
            return sizeof(*idl_h);
        }
        struct idl_txn idl_txn = { ch, idl_h->txid };
        status_t idl_st = ops->accept(ctx, idl_txn, idl_q->timeout_ms, &out_socket, &out_ring, &out_to_stack, &out_to_prog, &out_peer, &out_peer_port, &out_tx_bytes, &out_rx_bytes);
        /* IDL_LATER: the handler answers with net_reply_accept. */
        if (idl_st == IDL_LATER) {
            if (out_socket != HANDLE_INVALID)
                drv_handle_close(out_socket);
            if (out_ring != HANDLE_INVALID)
                drv_handle_close(out_ring);
            if (out_to_stack != HANDLE_INVALID)
                drv_handle_close(out_to_stack);
            if (out_to_prog != HANDLE_INVALID)
                drv_handle_close(out_to_prog);
            return 0;
        }
        idl_h->status = idl_st > 0 ? ERR_INTERNAL : idl_st;
        if (idl_h->status == OK && !(out_socket != HANDLE_INVALID && out_ring != HANDLE_INVALID && out_to_stack != HANDLE_INVALID && out_to_prog != HANDLE_INVALID))
            idl_h->status = ERR_INTERNAL;   /* a handle result left unset */
        if (idl_h->status != OK) {
            if (out_socket != HANDLE_INVALID)
                drv_handle_close(out_socket);
            if (out_ring != HANDLE_INVALID)
                drv_handle_close(out_ring);
            if (out_to_stack != HANDLE_INVALID)
                drv_handle_close(out_to_stack);
            if (out_to_prog != HANDLE_INVALID)
                drv_handle_close(out_to_prog);
            return sizeof(*idl_h);
        }
        rhs[0] = out_socket;
        rhs[1] = out_ring;
        rhs[2] = out_to_stack;
        rhs[3] = out_to_prog;
        *rhn = 4;
        idl_r->peer = out_peer;
        idl_r->peer_port = out_peer_port;
        idl_r->tx_bytes = out_tx_bytes;
        idl_r->rx_bytes = out_rx_bytes;
        return sizeof(*idl_r);
    }
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* net_dispatch_on without the channel (a `later` handler's txn then has none: use net_dispatch_on). */
static inline uint32_t net_dispatch(const struct net_ops *ops, void *ctx, const void *req, uint32_t n,
                                    void *rep, handle_t *rhs, uint32_t *rhn)
{
    return net_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* Take one message off ch and answer it. OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t net_serve_one(handle_t ch, const struct net_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[NET_REQ_MAX];
    _Alignas(8) uint8_t idl_r[NET_REP_MAX];
    handle_t idl_hs[IDL_READ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, sizeof(idl_q), &idl_n, idl_hs, IDL_READ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL)
        return idl_drain(ch, idl_n, idl_nh);
    if (idl_st != OK)
        return idl_st;
    if (idl_nh) {
        idl_close_all(idl_hs, idl_nh);
        idl_reply_status(ch, idl_q, idl_n, ERR_INVALID_ARGS);
        return OK;
    }
    handle_t idl_rhs[IDL_REP_HANDLES];
    uint32_t idl_rhn = 0;
    uint32_t idl_rn = net_dispatch_on(ch, ops, ctx, idl_q, idl_n, idl_r, idl_rhs, &idl_rhn);
    if (!idl_rn || drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn) != OK)
        idl_close_all(idl_rhs, idl_rhn);   /* not sent: they're still ours */
    return OK;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). */
static inline status_t net_serve(handle_t ch, const struct net_ops *ops, void *ctx)
{
    for (;;) {
        status_t idl_st = net_serve_one(ch, ops, ctx);
        if (idl_st == OK)
            continue;
        if (idl_st == ERR_PEER_CLOSED)
            return OK;
        if (idl_st != ERR_SHOULD_WAIT)
            return idl_st;
        signals_t idl_seen = 0;
        idl_st = drv_object_wait_one(ch, SIG_READABLE | SIG_PEER_CLOSED, DEADLINE_NEVER,
                                     &idl_seen);
        if (idl_st != OK)
            return idl_st;
    }
}
